from collections import deque

def min_delivery_time(n, m, deliveries):
    def bfs(start):
        queue = deque([(start, 0)])
        visited = [False] * (n + 1)
        visited[start] = True
        while queue:
            current, time = queue.popleft()
            for a, b in deliveries:
                if a == current:
                    if not visited[b]:
                        visited[b] = True
                        queue.append((b, time + 1))
                elif b == current:
                    if not visited[a]:
                        visited[a] = True
                        queue.append((a, time + 1))
        return sum(time for _, time in queue)

    return [bfs(i) for i in range(1, n + 1)]

